55	template <typename T, uint32_t dstM, uint32_t dstN>
56	CATLASS_DEVICE void
57	copy_gm_to_l1(LocalTensor<T> dstTensor, GlobalTensor<T> srcTensor,
58	              uint32_t realSrcN = 1, uint32_t realTailM = 0,
59	              uint32_t realTailN = 0, bool need_clear = true) {
60	  uint32_t tailM = realTailM == 0 ? dstM : realTailM;
61	  uint32_t tailN = realTailN == 0 ? dstN : realTailN;
62	  // Only the primary copy (dst offset 0, i.e. need_clear == true) is allowed to
63	  // zero-init the full L1 tile. Sub-region copies (need_clear == false, e.g.
64	  // the second DMA of a splice / vertical-merge pattern) must NOT clear,
65	  // otherwise they clobber data already written into the same NZ tile. The
66	  // full-tile clear is only correct when it targets the tile base, which the
67	  // codegen guarantees by passing need_clear = (dst_offset == 0).
68	  if (need_clear && (tailM != dstM || tailN != dstN)) {
69	    AscendC::InitConstValue(
70	        dstTensor,
71	        {1, static_cast<uint16_t>(dstM * dstN * sizeof(T) / 32), 0, 0});
72	    AscendC::PipeBarrier<PIPE_MTE2>();
73	  }
74	  auto layout = MakeLayoutFromTag(LayoutGM{tailM, realSrcN});
75	  auto src_LAYOUT = MakeLayoutTile(layout, tla::MakeShape(tailM, tailN));
76	  auto src = tla::MakeTensor<decltype(srcTensor), decltype(src_LAYOUT),
77	                             AscendC::TPosition::GM>(srcTensor, src_LAYOUT);
78	
79	  using LayoutL1_ = Catlass::detail::TagToLayout_t<T, LayoutL1>;
80	  constexpr auto layoutInL1 = tla::MakeLayout<T, LayoutL1_>(dstM, dstN);
81	  auto dst = tla::MakeTensor<decltype(dstTensor), decltype(layoutInL1),
82	                             AscendC::TPosition::A1>(dstTensor, layoutInL1);
83	
84	  TileCopyTla<ArchTag, decltype(src), decltype(dst)> tileCopier;
85	  tileCopier(dst, src);
86	}
87	
88	template <typename T, uint32_t srcM, uint32_t srcN, bool transpose = false>
89	CATLASS_DEVICE void copy_l1_to_l0a(LocalTensor<T> dstTensor,
90	                                   LocalTensor<T> srcTensor, uint32_t dstM,
91	                                   uint32_t dstN) {
92	  using LayoutL1_ =
93	      std::conditional_t<transpose,
94	                         Catlass::detail::TagToLayout_t<T, LayoutL1T>,
95	                         Catlass::detail::TagToLayout_t<T, LayoutL1>>;
96	  constexpr auto layout = transpose ? tla::MakeLayout<T, LayoutL1_>(srcN, srcM)
97	                                    : tla::MakeLayout<T, LayoutL1_>(srcM, srcN);
98	  auto src_LAYOUT = MakeLayoutTile(layout, tla::MakeShape(dstM, dstN));
99	  auto src = MakeTensor<decltype(srcTensor), decltype(src_LAYOUT),
100	                        AscendC::TPosition::A1>(srcTensor, src_LAYOUT);
101	
102	  using LayoutL0A_ = Catlass::detail::TagToLayout_t<T, LayoutL0A>;
103	  auto layoutAInL0 = tla::MakeLayout<T, LayoutL0A_>(dstM, dstN);
104	  auto dst = tla::MakeTensor<decltype(dstTensor), decltype(layoutAInL0),
105	                             AscendC::TPosition::A2>(dstTensor, layoutAInL0);
106	  TileCopyTla<ArchTag, decltype(src), decltype(dst)> tileCopier;
107	  tileCopier(dst, src);
108	}
