117	                         Catlass::detail::TagToLayout_t<T, LayoutL1>>;
118	  constexpr auto layout = transpose ? tla::MakeLayout<T, LayoutL1_>(srcN, srcM)
119	                                    : tla::MakeLayout<T, LayoutL1_>(srcM, srcN);
120	  auto src_LAYOUT = MakeLayoutTile(layout, tla::MakeShape(dstM, dstN));
121	  auto src = MakeTensor<decltype(srcTensor), decltype(src_LAYOUT),
122	                        AscendC::TPosition::A1>(srcTensor, src_LAYOUT);
