133	template <typename T1, typename T2, uint32_t M, uint32_t N>
134	CATLASS_DEVICE void mma(LocalTensor<T1> const A, LocalTensor<T1> const B,
135	                        LocalTensor<T2> const C, bool init, uint32_t K,
136	                        uint32_t n_actual = N, uint8_t unitFlag = 0) {
137	  // n_actual: runtime number of output columns to compute (<= N). Defaults to
138	  // the compile-time N, so existing callers are byte-identical. Enables
139	  // variable-N gemm (e.g. QK over the actual window length), mirroring how K is
140	  // already a runtime arg.
141	  MmadParams mmadParams;
142	  mmadParams.m = M;
143	  mmadParams.n = n_actual;
144	  mmadParams.k = K;
145	  mmadParams.cmatrixInitVal = init;
146	  // MmadParams does not default-initialise cmatrixSource, and the hardware
147	  // reads it whenever cmatrixInitVal == false (an accumulating mma, C sourced
148	  // from L0C). A single-mma caller never notices, but a K-accumulating sequence
149	  // that also sets unitFlag reads the uninitialised field and hangs the cube.
150	  // false ("source from L0C") is what every accumulating caller already means.
151	  mmadParams.cmatrixSource = false;
152	  // unitFlag drives the hardware mma->fixpipe pipeline: 0b10 keeps the result
153	  // in L0C, 0b11 releases it to a paired fixpipe. That is what lets
154	  // fixpipe(tile i) overlap mma(tile i+1) across a two-slot L0C ping-pong,
155	  // without a software M_FIX/FIX_M handshake. Defaults to 0 (off), so every
156	  // existing caller is byte-for-byte unchanged.
157	  mmadParams.unitFlag = unitFlag;
158	
159	  Mmad(C, A, B, mmadParams);
160	
161	  constexpr uint32_t PIPE_M_BARRIER_THRESHOLD = 10;
162	  // if constexpr ((M / C0_NUM_PER_FRACTAL) * (N / C0_NUM_PER_FRACTAL) <
163	  //               PIPE_M_BARRIER_THRESHOLD) {
164	  //   PipeBarrier<PIPE_M>();
165	  // }
166	}
167	
168	template <typename T1, typename T2, typename LayoutGM, uint32_t srcM,
169	          uint32_t srcN, bool enRelu = false>
170	CATLASS_DEVICE void
171	copy_l0c_to_gm(GlobalTensor<T2> dstTensor, LocalTensor<T1> srcTensor,
172	               uint32_t realDstN = 1, uint32_t realTailM = 0,
173	               uint32_t realTailN = 0, uint8_t unitFlag = 0) {
174	  uint32_t tailM = realTailM == 0 ? srcM : realTailM;
175	  uint32_t tailN = realTailN == 0 ? srcN : realTailN;
176	  auto layoutInL0C = tla::MakeLayoutL0C(srcM, srcN);
177	  auto src = tla::MakeTensor<decltype(srcTensor), decltype(layoutInL0C),
178	                             AscendC::TPosition::CO1>(srcTensor, layoutInL0C);
179	  LayoutGM gm{tailM, realDstN};
180	  auto layout = MakeLayoutFromTag(gm);
181	  auto dTensor = MakeTensor(dstTensor, layout, Arch::PositionGM{});
182	  auto layout_ = dTensor.layout();
183	  auto dst_LAYOUT = MakeLayoutTile(layout_, tla::MakeShape(tailM, tailN));
184	  auto dst = MakeTensor<decltype(dstTensor), decltype(dst_LAYOUT),
185	                        AscendC::TPosition::GM>(dstTensor, dst_LAYOUT);
186	
187	  CopyL0CToGmTla<ArchTag, decltype(src), decltype(dst),
188	                 ScaleGranularity::NO_QUANT, enRelu>
189	      tileCopier;
190	  // unitFlag (default 0 = a standalone fixpipe) pairs with the Mmad unitFlag to
191	  // form the hardware mma->fixpipe pipeline; CopyL0CToGmTla already plumbs it
192	  // through to FixpipeParams.
193	  tileCopier(dst, src, unitFlag);
194	}
