196	template <uint32_t M, uint32_t N, uint32_t K, uint32_t block_M,
197	          uint32_t block_N, uint32_t SwizzleOffset = 1,
198	          uint32_t SwizzleDirection = 0>
199	CATLASS_DEVICE auto thread_block_swizzle(uint64_t pid) {
200	  GemmCoord problem_shape = GemmCoord(M, N, K);
201	  MatrixCoord tile_shape = MatrixCoord(block_M, block_N);
